-- ════════════════════════════════════════════════════════════════════
-- Surzur, Fruits de mer : mêmes photos que Paris pour les bulots et les crevettes,
-- et assiette Capitaine moins zoomée (le plat occupe ~2/3 de l'image, comme à Paris).
-- Touche le vrai site de Surzur et sa copie de test. Sans danger si relancé.
-- ════════════════════════════════════════════════════════════════════
update public.menu_data
set data = jsonb_set(jsonb_set(jsonb_set(data,
      '{tabs,1,cards,0,dishes,0,img}', to_jsonb('data:image/webp;base64,'::text)),
      '{tabs,1,cards,0,dishes,1,img}', to_jsonb('data:image/webp;base64,'::text)),
      '{tabs,1,cards,0,dishes,2,img}', to_jsonb('data:image/webp;base64,'::text)),
    updated_at = now()
where client_slug in ('drevici-surzur', 'drevici-surzur-test')
  and data #>> '{tabs,1,cards,0,dishes,0,_pid}' = 'd_mr42kcb2vaq5bn'
  and data #>> '{tabs,1,cards,0,dishes,1,_pid}' = 'd_mr42kcb2nayvm6'
  and data #>> '{tabs,1,cards,0,dishes,2,_pid}' = 'd_surz_capitaine';

-- Vérification : 2 lignes, chacune avec 3 photos intégrées
select client_slug, (select count(*) from jsonb_array_elements(data #> '{tabs,1,cards,0,dishes}') x where x->>'img' like 'data:image%') as photos_integrees
from public.menu_data where client_slug in ('drevici-surzur', 'drevici-surzur-test');
